import Link from "next/link";
import { ArrowUpRight, Bot, BrainCircuit, ChartNoAxesCombined, Check, Clock3, LockKeyhole, MessageCircle, Newspaper, Pause, Play, Radar, RefreshCw, Settings2, ShieldAlert, ShieldCheck, Square, Wallet } from "lucide-react";
import type { ComponentType, FormEvent } from "react";
import { AGENT_ROLES, AGENT_ROLE_LABELS, AGENT_ROLE_MISSIONS, DEFAULT_DESK_OPERATIONS, DEFAULT_DESK_SCOUTING, type AgentDeskCommand, type AgentDeskView, type AgentEvidence, type AgentFinding, type AgentRole, type DeskCycle, type DeskSettings } from "@/lib/agent-desk/contracts";
import type { DeskPolicy, DeskQuote } from "@/lib/agent-desk/guardrails";
import type { DeskResearchTools } from "@/lib/agent-desk/research-tool-types";
import { safeResearchSourceUrl } from "@/lib/intelligence/research-evidence";
import { IntelligencePage } from "./intelligence-ui";
import { ConfidenceCalculation } from "./score-decision-panel";
import FounderAgentCollaboration from "./agent-collaboration";
import AgentOperationsView from "./agent-operations-view";
import FounderBrokerProposal from "@/components/agent-broker/broker-proposal-approval";
import css from "./agent-desk.module.css";

const fmt = (value: number | null | undefined, digits = 2) => typeof value === "number" && Number.isFinite(value) ? value.toLocaleString("en-US", { maximumFractionDigits: digits, minimumFractionDigits: digits }) : "—";
const money = (value: number | null | undefined) => typeof value === "number" && Number.isFinite(value) ? value.toLocaleString("en-US", { style: "currency", currency: "USD" }) : "—";
const time = (value: string | null | undefined) => value && Number.isFinite(Date.parse(value)) ? /^\d{4}-\d{2}-\d{2}$/.test(value) ? `${value} · date only` : new Date(value).toLocaleString("en-US", { timeZone: "America/New_York", year: "numeric", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }) + " ET" : "Not recorded";
const ROLE_ICONS: Record<AgentRole, ComponentType<{ size?: number; "aria-hidden"?: boolean }>> = { chief: BrainCircuit, sentiment: MessageCircle, scout: Radar, news: Newspaper, skeptic: ShieldAlert, charts: ChartNoAxesCombined };
const ROLE_TAGS: Record<AgentRole, string> = { chief: "Consolidation & final decision", sentiment: "Economy & investor appetite", scout: "Continuous candidate discovery", news: "Media & candidate catalysts", skeptic: "Historical scenarios & challenge", charts: "Technicals & market viability" };
const evidenceKind = (kind: AgentEvidence["kind"]) => kind === "scored-evidence" ? "Scored evidence" : kind === "execution-reference" ? "Execution reference · unscored" : kind === "tool-research" ? "Research tool · unscored" : "Public discovery · unscored";
const lastFinding = (findings: AgentFinding[], role: AgentRole) => [...findings].reverse().find(finding => finding.role === role);
const stateLabel = (desk: AgentDeskView) => desk.controls.killSwitch ? "Kill switch engaged" : !desk.controls.armed ? "Research only" : desk.controls.paused ? "Entries paused" : desk.controls.autonomous ? "Autonomous paper" : "Manual paper approvals";
const actionLabel = (cycle: DeskCycle | null) => !cycle ? "Waiting for the first cycle" : cycle.executionStatus === "filled" ? `Paper ${cycle.fill?.side === "BUY" ? "purchase" : "sale"} recorded` : cycle.executionStatus === "awaiting-approval" ? "Paper proposal awaiting approval" : cycle.executionStatus === "blocked" ? "Entry or execution blocked" : cycle.executionStatus === "failed" ? "Cycle needs attention" : "Hold · no paper order";
function researchHref(cycle: DeskCycle | null, symbol?: string) {
  return `/workspace/intelligence?${new URLSearchParams({ symbol: cycle?.symbol ?? symbol ?? "MSFT", ...(cycle?.researchRunId ? { researchRunId: cycle.researchRunId } : {}) })}`;
}

export type AgentDeskDashboardProps = {
  desk: AgentDeskView | null; draft: DeskSettings | null; symbolsText: string; scoutUniverseText: string; dirty: boolean; conflict: boolean; loading: boolean;
  pending: AgentDeskCommand["action"] | null; error: string; message: string; incomingSymbol: string | null;
  onAction: (action: Exclude<AgentDeskCommand["action"], "settings">) => void; onReload: () => void; onDiscard: () => void; onSave: () => void;
  onDraft: (update: (value: DeskSettings) => DeskSettings) => void; onSymbols: (value: string) => void; onScoutUniverse: (value: string) => void; onUseIncoming: () => void;
};

export default function AgentDeskDashboard(props: AgentDeskDashboardProps) {
  const { desk, draft, loading, pending, error, message, dirty, conflict } = props;
  const cycle = desk?.latestCycle ?? null, account = desk?.account;
  const brokerTarget = cycle?.executionTarget === "alpaca-live" || cycle?.executionTarget === "alpaca-paper";
  const executionLabel = cycle?.executionTarget === "alpaca-live" ? "Alpaca live brokerage" : cycle?.executionTarget === "alpaca-paper" ? "Alpaca paper brokerage" : "Local paper simulation";
  const researchCycle = cycle?.agents.length ? cycle : desk?.history.find(item => item.agents.length > 0) ?? null;
  const blocked = !desk || loading || Boolean(pending) || Boolean(desk.busy) || Boolean(desk.scouting?.busy) || dirty || Boolean(error);
  const providersMissing = !desk || desk.providers.ai === "missing" || desk.providers.market === "missing";
  const readyAction = !blocked && !providersMissing && !desk?.controls.killSwitch;
  const policyLocked = !desk || Boolean(pending) || Boolean(desk.busy) || Boolean(desk.scouting?.busy) || (desk.controls.armed && !desk.controls.paused && !desk.controls.killSwitch);
  const observedPrice = typeof account?.lastObservedPrice === "number" && Number.isFinite(account.lastObservedPrice) ? account.lastObservedPrice : null;
  const equity = account?.position ? observedPrice === null ? null : account.cash + account.position.quantity * observedPrice : account?.cash;
  const unrealizedPnl = account?.position && observedPrice !== null ? account.position.quantity * (observedPrice - account.position.averageEntry) - account.position.entryFees : null;
  const latestSource = researchCycle?.evidence.reduce<string | null>((latest, item) => item.observedAt && Number.isFinite(Date.parse(item.observedAt)) && (!latest || Date.parse(item.observedAt) > Date.parse(latest)) ? item.observedAt : latest, null) ?? null;
  return <IntelligencePage><div className={css.desk}>
    <header className={css.hero}><div><p className={css.eyebrow}><Bot size={14} aria-hidden />Slice / founder’s six-agent desk</p><h1>Your team.<br />Your safeguards.</h1><p>Six specialists share evidence, challenge each other, and review their recorded outcomes. Chief consolidates the discussion into one documented decision. Follow every exchange in the Team Board. Your Brief keeps local simulation results and broker-confirmed executions in separate sections.</p><div className={css.actions}><Link className={css.textButton} href="/workspace/team-board#founder-agent-channel" prefetch={false}>Team conversation<ArrowUpRight size={13} aria-hidden /></Link><Link className={css.textButton} href="/workspace/brief" prefetch={false}>Your trade briefs<ArrowUpRight size={13} aria-hidden /></Link><Link className={css.textButton} href="/workspace/settings#founder-broker" prefetch={false}>Broker controls &amp; receipts<ArrowUpRight size={13} aria-hidden /></Link></div></div><div className={css.heroIcon} aria-hidden><BrainCircuit /></div></header>
    <div className={css.topline}><div className={css.pills}><span className={css.pill}><LockKeyhole size={12} aria-hidden />Founder access</span><span className={css.pill}><Wallet size={12} aria-hidden />Paper account · simulated fills</span><Link className={css.textButton} href="/workspace/settings#founder-broker" prefetch={false}>Broker connection &amp; permissions<ArrowUpRight size={12} aria-hidden /></Link>{desk && <span className={css.pill} data-tone={desk.controls.killSwitch ? "negative" : desk.controls.autonomous && !desk.controls.paused ? "positive" : "caution"}>{stateLabel(desk)}</span>}</div><Link className={css.textButton} href={researchHref(researchCycle, desk?.settings.symbol)} prefetch={false}>Open evidence graph<ArrowUpRight size={13} aria-hidden /></Link></div>
    {loading && !desk && <div className={css.notice} role="status"><RefreshCw size={14} className={css.loading} aria-hidden /> Loading your private agent team and paper account…</div>}
    {error && <div className={css.notice} data-tone="negative" role="alert"><strong>Desk needs attention</strong><p>{error}</p><button type="button" className={css.textButton} onClick={props.onReload} disabled={Boolean(pending)}>Reload current state<RefreshCw size={12} aria-hidden /></button></div>}
    {message && <div className={css.notice} data-tone="positive" role="status">{message}</div>}
    {desk && <>
      {providersMissing && <div className={css.notice} data-tone="caution"><strong>Connect the required research services</strong><p>{desk.providers.ai === "missing" ? "The server needs OPENAI_API_KEY for the six AI roles. " : ""}{desk.providers.market === "missing" ? "The server needs ALPHA_VANTAGE_API_KEY for observed market data. " : ""}Provider keys are managed in the server environment. They are never entered into this trading desk.</p></div>}
      {props.incomingSymbol && props.incomingSymbol !== desk.settings.symbol && <div className={css.notice}><strong>You arrived from {props.incomingSymbol} research.</strong><p>This desk currently monitors {desk.settings.symbol}. Choose the new symbol in safeguards and save before running it.</p><button type="button" className={css.textButton} onClick={props.onUseIncoming} disabled={policyLocked || Boolean(account?.position)}>Use {props.incomingSymbol} in draft settings<ArrowUpRight size={12} aria-hidden /></button></div>}
      <div className={css.actions}>
        <button type="button" className={css.button} onClick={() => props.onAction("cycle")} disabled={!readyAction}>{pending === "cycle" || desk.busy ? <RefreshCw size={14} className={css.loading} aria-hidden /> : <Radar size={14} aria-hidden />}{desk.busy ? "Cycle in progress" : `Analyze ${desk.settings.symbol} now`}</button>
        {(!desk.controls.armed || desk.controls.paused) && !desk.controls.killSwitch && <button type="button" className={css.secondary} onClick={() => props.onAction("arm")} disabled={!readyAction}><Check size={14} aria-hidden />Enable manual paper approvals</button>}
        {(!desk.controls.autonomous || desk.controls.paused) && !desk.controls.killSwitch && <button type="button" className={css.secondary} onClick={() => props.onAction("enable")} disabled={!readyAction}><Play size={14} aria-hidden />Start autonomous paper trading</button>}
        {desk.controls.armed && !desk.controls.paused && !desk.controls.killSwitch && <button type="button" className={css.secondary} onClick={() => props.onAction("pause")} disabled={pending === "pause" || pending === "kill"}><Pause size={14} aria-hidden />Pause new entries</button>}
        {desk.controls.killSwitch ? <button type="button" className={css.secondary} onClick={() => props.onAction("resume")} disabled={Boolean(pending) || Boolean(desk.busy) || dirty}><Play size={14} aria-hidden />Resume desk · autonomy stays off</button> : <button type="button" className={css.danger} onClick={() => props.onAction("kill")} disabled={pending === "kill"}><Square size={13} aria-hidden />Stop desk &amp; new broker entries</button>}
        <button type="button" className={css.textButton} onClick={props.onReload} disabled={Boolean(pending)}><RefreshCw size={13} aria-hidden />Reload</button>
      </div>
      <p className={css.fine}>{dirty ? "Save or discard your safeguard edits before starting a cycle or changing execution mode. " : ""}To review an order manually, enable manual paper approvals before running its research cycle. Starting autonomy authorizes simulated orders within your saved safeguards. The same safeguards are checked before every paper fill.</p>
      <div className={css.notice}><strong><Clock3 size={13} aria-hidden /> Continuous operation needs a running worker</strong><p>Keep <code>{desk.worker.command}</code> running locally, or use the configured hosted scheduler. That worker runs autonomous cycles and checks protective exits when this page is closed. Last worker check: {time(desk.worker.lastCheckedAt)}. Next scheduled cycle: {time(desk.nextRunAt)}.</p><p className={css.fine}>Scheduled research waits for the modeled US regular session and a usable live provider observation. Manual analysis remains available outside market hours. Checks run at the worker’s actual processing cadence, without a guaranteed execution time.</p><p className={css.fine}>Pause stops new entries in the local simulation and at the broker while armed protective checks continue. The kill switch stops all local simulated fills and revokes new broker entries. Broker-native protective orders and the worker’s broker risk monitoring and reconciliation remain active. Neither control liquidates positions. Exit thresholds are checked on usable observations; their execution price is not guaranteed.</p></div>
      {desk.busy && <div className={css.notice} role="status"><strong><span className={css.runningSignal} aria-hidden style={{ display: "inline-block", marginRight: 7 }} />{desk.busy.stage || "Research cycle running"}</strong><p>{fmt(desk.busy.progress, 0)}% recorded job progress · Started {time(desk.busy.startedAt)}. The cards below retain the last completed cycle until the new results are saved.</p><progress className={css.progress} max={100} value={Math.max(0, Math.min(100, desk.busy.progress))} aria-label="Recorded agent cycle progress" /></div>}
      {desk.lastError && <div className={css.notice} data-tone="negative" role="alert"><strong>Last worker or cycle error</strong><p>{desk.lastError}</p></div>}
      {account?.reviewRequired && <div className={css.notice} data-tone="caution"><strong>Open position needs review</strong><p>This position crossed a trading-session boundary. The system has not invented split or dividend adjustments. Review the recorded position and data before resuming entries.</p></div>}
      <div className={css.overview} aria-label="Recorded paper account metrics">
        <div className={css.stat}><span>Last recorded equity</span><strong>{money(equity)}</strong><small>{account?.position ? `Market mark: ${time(account.lastObservedAt)}` : "Cash account · no open position"}</small></div>
        <div className={css.stat}><span>Available paper cash</span><strong>{money(account?.cash)}</strong><small>Starting capital {money(account?.initialCapital)}</small></div>
        <div className={css.stat} data-tone={(account?.realizedPnl ?? 0) < 0 ? "negative" : "positive"}><span>Recorded realized P&amp;L</span><strong>{money(account?.realizedPnl)}</strong><small>Simulated fees paid {money(account?.feesPaid)}</small></div>
        <div className={css.stat}><span>Orders this session</span><strong>{fmt(account?.session.trades, 0)} / {fmt(desk.settings.policy.maxTradesPerDay, 0)}</strong><small>{account?.session.date} · Daily loss limit {fmt(desk.settings.policy.maxDailyLossPct, 1)}%{account?.session.lossHalted ? " · Entries halted" : ""}</small></div>
      </div>
    </>}

    <section className={css.section} aria-label="Six AI roles and their recorded findings">
      <div className={css.sectionHead}><div><p className={css.eyebrow}><BrainCircuit size={13} aria-hidden />The deliberation team</p><h2>Six roles. One accountable decision.</h2><p>{researchCycle ? `Last recorded AI cycle: ${researchCycle.symbol} · ${time(researchCycle.completedAt)}. Every claim can be traced to the evidence available to that run.` : "The specialists examine the evidence, the skeptic challenges it, and the chief proposes an action. Findings appear after actual AI calls complete; an empty account contains no generated trading history."}</p></div>{researchCycle && <Link className={css.secondary} href={researchHref(researchCycle)} prefetch={false}>Inspect this research run<ArrowUpRight size={13} aria-hidden /></Link>}</div>
      <div className={css.decision} data-action={cycle?.executionStatus === "blocked" || cycle?.executionStatus === "failed" ? "blocked" : cycle?.proposal?.action ?? "hold"}>
        <div><span className={css.pill}>{cycle?.symbol ?? desk?.settings.symbol ?? "Selected instrument"} · {executionLabel}</span><h3>{brokerTarget ? `${executionLabel} · ${cycle?.proposal?.action.toUpperCase() || "HOLD"} proposal` : actionLabel(cycle)}</h3>{brokerTarget && <p className={css.fine}>Local simulation review: {actionLabel(cycle)}. This local status is separate from broker acceptance or a confirmed fill.</p>}<p>{cycle?.decision?.message || cycle?.proposal?.rationale || "Configure your safeguards, then analyze an instrument to collect the first source-grounded team decision."}</p>{cycle?.decision?.reasons.length ? <ul>{cycle.decision.reasons.map((reason, index) => <li key={index} className={css.fine}>{reason}</li>)}</ul> : null}{cycle?.executionStatus === "awaiting-approval" && desk && !brokerTarget && <><button type="button" className={css.button} disabled={blocked || desk.controls.paused || desk.controls.killSwitch || !desk.controls.armed || cycle.settingsRevision !== desk.revision} onClick={() => props.onAction("approve")}><Check size={14} aria-hidden />Approve this paper proposal</button>{cycle.settingsRevision !== desk.revision && <p className={css.warningText}>Your safeguards or execution controls changed after this proposal. Run a new research cycle before approving an order.</p>}</>}</div>
        <dl><div><dt>Research confidence</dt><dd>{fmt(cycle?.researchScore?.confidence, 1)} / 100</dd></div><div><dt>Your entry confidence floor</dt><dd>{fmt(desk?.settings.policy.minResearchConfidence, 0)} / 100</dd></div><div><dt>Evidence coverage</dt><dd>{fmt(cycle?.researchScore?.quality.evidenceCoverage, 1)} / 100</dd></div><div><dt>Skeptic review</dt><dd>{cycle?.agents.find(agent => agent.role === "skeptic")?.veto ? "Veto · new exposure blocked" : cycle?.agents.find(agent => agent.role === "skeptic")?.status === "complete" ? "Completed" : "Not complete"}</dd></div><div><dt>Execution target</dt><dd>{executionLabel}</dd></div><div><dt>Chief proposal</dt><dd>{cycle?.proposal?.action ? `${cycle.proposal.action.toUpperCase()}${cycle.proposal.allocationPct !== null ? ` · ${fmt(cycle.proposal.allocationPct, 1)}% allocation` : ""}` : "Not available"}</dd></div></dl>
      </div>
      {cycle && brokerTarget && <FounderBrokerProposal cycle={cycle} />}
      {cycle && <ObservedPriceAudit cycle={cycle} />}
      {researchCycle && researchCycle.id !== cycle?.id && <p className={css.notice}>The latest paper check above is separate from the last AI deliberation. These cards and their source records retain the AI cycle from {time(researchCycle.completedAt)}; the protective check did not produce new agent research.</p>}
      {researchCycle?.deliberation && <div className={css.pills}><span className={css.pill}>{researchCycle.deliberation.rounds} recorded rounds</span><span className={css.pill}>{researchCycle.deliberation.reports} actual reports</span><span className={css.pill}>{researchCycle.deliberation.messages} saved messages</span><span className={css.pill} data-tone={researchCycle.deliberation.complete ? "positive" : "caution"}>{researchCycle.deliberation.complete ? "Deliberation complete" : "Deliberation incomplete"}</span></div>}
      <div className={css.roles}>{AGENT_ROLES.map(role => <AgentRoleCard key={role} role={role} finding={lastFinding(researchCycle?.agents ?? [], role)} evidence={researchCycle?.evidence ?? []} />)}</div>
      {researchCycle?.researchScore && <div style={{ marginTop: 15 }}><ConfidenceCalculation audit={researchCycle.researchScore.confidenceAudit ?? null} /></div>}
      <p className={css.fine}>The six roles share recorded sources and may use the same underlying model. Their agreement is not six independent data sources or a calibrated probability of profit. The execution controls remain separate from the AI proposal.</p>
    </section>

    {desk && <AgentOperationsView desk={desk} cycle={researchCycle} />}
    {desk && <ScoutDiscoveryPanel desk={desk} disabled={blocked || providersMissing || desk.controls.killSwitch} onScan={() => props.onAction("scout")} />}
    <AgentResearchTools tools={researchCycle?.researchTools ?? null} symbol={researchCycle?.symbol ?? desk?.settings.symbol ?? "MSFT"} />
    {desk && draft && <DeskSettingsForm desk={desk} draft={draft} symbolsText={props.symbolsText} scoutUniverseText={props.scoutUniverseText} disabled={policyLocked} dirty={dirty} conflict={conflict} pending={pending}
      onDraft={props.onDraft} onSymbols={props.onSymbols} onScoutUniverse={props.onScoutUniverse} onSave={props.onSave} onDiscard={props.onDiscard} />}
    {desk && <FounderAgentCollaboration mode="desk" />}

    {desk && <div className={css.split}>
      <section className={css.section} aria-label="Paper position and recent fills"><div className={css.sectionHead}><div><h2>Paper position &amp; execution</h2><p>Whole-share, long-only simulation with one open position. Slippage and fees are applied to observed prices.</p></div></div>
        {account?.position ? <><div className={css.tableWrap}><table className={css.table}><caption>Open position · exit rules recorded at entry</caption><thead><tr><th scope="col">Instrument</th><th scope="col">Shares</th><th scope="col">Average fill</th><th scope="col">Unrealized P&amp;L</th></tr></thead><tbody><tr><th scope="row">{account.position.symbol}</th><td>{fmt(account.position.quantity, 0)}</td><td>{money(account.position.averageEntry)}</td><td>{money(unrealizedPnl)}</td></tr></tbody></table></div><p className={css.fine}>Opened {time(account.position.openedAt)}. Stop {fmt(account.position.stopLossPct, 1)}%; take-profit {account.position.takeProfitPct === null ? "off" : `${fmt(account.position.takeProfitPct, 1)}%`}; trailing stop {account.position.trailingStopPct === null ? "off" : `${fmt(account.position.trailingStopPct, 1)}%`}; maximum hold {fmt(account.position.maxHoldingMinutes, 0)} minutes; close {fmt(account.position.flattenBeforeCloseMinutes, 0)} minutes before the modeled regular session ends.</p></> : <div className={css.empty}><strong>No open paper position</strong>Capital remains in simulated cash until an eligible proposal passes your controls.</div>}
        <RecentFills cycles={desk.history} />
      </section>
      <section className={css.section} aria-label="Recorded agent cycles"><div className={css.sectionHead}><div><h2>Decision history</h2><p>Recent saved cycles, including holds, blocked entries, errors, and protective exits.</p></div></div>{desk.history.length ? <ol className={css.log}>{desk.history.map(item => <li key={item.id}><div className={css.logHead}><strong>{item.symbol} · {item.executionStatus.replace(/-/g, " ")}</strong><time dateTime={item.completedAt}>{time(item.completedAt)}</time></div><p>{item.decision?.message || item.proposal?.rationale || item.errors[0] || "The run was saved without an executable proposal."}</p><details><summary>Inspect the recorded decision</summary><p>Research confidence {fmt(item.researchScore?.confidence, 1)} / 100 · Paper cycle {item.id}</p>{item.decision?.reasons.length ? <ul>{item.decision.reasons.map((reason, index) => <li key={index}>{reason}</li>)}</ul> : null}{item.errors.length > 0 && <ul>{item.errors.map((reason, index) => <li key={index}>{reason}</li>)}</ul>}{item.researchRunId && <Link href={researchHref(item)} prefetch={false}>Open the matching research and source trail</Link>}</details></li>)}</ol> : <div className={css.empty}><strong>No cycles recorded yet</strong>Completed work appears here with its actual outcome and source trail.</div>}</section>
    </div>}

    {researchCycle && <section className={css.section} aria-label="Evidence shared with the AI team"><div className={css.sectionHead}><div><h2>Shared evidence room</h2><p>{researchCycle.evidence.length} records available to the {researchCycle.symbol} AI cycle from {time(researchCycle.completedAt)}. Public discoveries and execution references are labeled separately and do not add confidence votes. Latest recorded publication or observation: {time(latestSource)}.</p></div><Link className={css.textButton} href={`${researchHref(researchCycle)}#research-sources`} prefetch={false}>Full research archive<ArrowUpRight size={13} aria-hidden /></Link></div>{researchCycle.evidence.length ? <details><summary className={css.textButton}>Inspect the team’s source records</summary><ul className={css.sourceList}>{researchCycle.evidence.map(item => <EvidenceLink key={item.id} evidence={item} />)}</ul></details> : <div className={css.empty}>No verified source records were available to this cycle. The team cannot invent evidence to authorize an entry.</div>}</section>}
    <footer className={css.footer}><span><ShieldCheck size={12} aria-hidden style={{ display: "inline", verticalAlign: "-2px", marginRight: 5 }} />This ledger records local paper fills. Broker balances, order acknowledgments, and execution permissions are shown separately in Settings.</span><span>{desk ? `Account updated ${time(desk.updatedAt)} · Policy revision ${desk.revision}` : "Private account state has not loaded."}</span></footer>
  </div></IntelligencePage>;
}

export function ObservedPriceAudit({ cycle }: { cycle: DeskCycle }) {
  const quotes = [cycle.contextQuote, cycle.executionQuote];
  const rows: Array<{ label: string; value: (quote: DeskQuote) => string }> = [
    { label: "Instrument", value: quote => `${quote.symbol} · ${quote.instrumentKind}` },
    { label: "Provider listing venue", value: quote => quote.exchange || "Not recorded" },
    { label: "Recorded provider price", value: quote => `${quote.currency} ${Number.isFinite(quote.price) ? String(quote.price) : "Unavailable"}` },
    { label: "Source kind", value: quote => quote.sourceKind === "intraday-bar" ? "Intraday bar" : quote.sourceKind === "daily" ? "Daily observation" : "Provider quote" },
    { label: "Original observation time", value: quote => quote.observedAt },
    { label: "Provider response received", value: quote => quote.retrievedAt },
    { label: "Real-time status", value: quote => quote.realTimeConfirmed ? "Confirmed by provider" : "Not confirmed" },
    { label: "Market status", value: quote => quote.marketOpen ? "Open in the recorded check" : "Closed or not confirmed open" },
  ];
  return <details className={css.priceAudit}>
    <summary>Observed price audit</summary>
    <p>Prices and timestamps belong to this saved decision. A bar reference price is not an executable bid/ask quote. A recorded observation can still fail the execution safeguards; simulated fills apply the saved cost assumptions.</p>
    {quotes.some(Boolean) ? <div className={css.tableWrap}><table className={css.table}>
      <caption>Observed prices for {cycle.symbol} · {cycle.id}</caption>
      <thead><tr><th scope="col">Recorded input</th><th scope="col">Before AI deliberation</th><th scope="col">At execution check</th></tr></thead>
      <tbody>{rows.map(row => <tr key={row.label}><th scope="row">{row.label}</th>{quotes.map((quote, index) => <td key={index}>{quote ? <span className={row.label.includes("time") || row.label.includes("received") ? css.mono : undefined}>{row.value(quote)}</span> : "Not recorded"}</td>)}</tr>)}</tbody>
    </table></div> : <p>No separate context or execution quote was recorded for this cycle. A current price is not substituted into an older decision.</p>}
    {cycle.sourceHash && <p className={css.mono}>Recorded source hash: {cycle.sourceHash}</p>}
  </details>;
}

export function ScoutDiscoveryPanel({ desk, disabled, onScan }: { desk: AgentDeskView; disabled: boolean; onScan: () => void }) {
  const scouting = desk.settings.scouting ?? DEFAULT_DESK_SCOUTING, discovery = desk.scouting?.discovery;
  return <section className={css.section} aria-label="Scout candidate discovery"><div className={css.sectionHead}><div><p className={css.eyebrow}><Radar size={13} aria-hidden />Scout / opportunity discovery</p><h2>Keep a watch on what changes.</h2><p>Scout ranks observed candidates for Intelligence research. Sources, publication times, and discovery reasons remain visible; the founder’s separate trading allowlist controls which instruments may open paper positions.</p></div><button type="button" className={css.secondary} onClick={onScan} disabled={disabled}>{desk.scouting?.busy ? <RefreshCw size={13} className={css.loading} aria-hidden /> : <Radar size={13} aria-hidden />}{desk.scouting?.busy ? "Scout scan running" : "Scan candidates now"}</button></div>
    <div className={css.pills}><span className={css.pill}>{scouting.enabled ? `Scheduled every ${scouting.intervalMinutes} minutes` : "Scheduled discovery off"}</span><span className={css.pill}>{scouting.enabled && scouting.autoResearch ? "Automatic candidate research enabled" : "Candidate research on review"}</span><span className={css.pill}>Trading allowlist remains separate</span></div>
    <p className={css.fine}>Last scan: {time(desk.scouting?.lastScanAt)} · Next scan: {time(desk.scouting?.nextScanAt)}. Configure the research universe and scheduling in safeguards below.</p>
    {desk.scouting?.busy && <p className={css.notice} role="status">Scout is collecting candidate observations. Started {time(desk.scouting.busy.startedAt)}. The saved results below retain their original timestamps.</p>}
    {desk.scouting?.lastError && <p className={css.notice} data-tone="negative" role="alert">{desk.scouting.lastError}</p>}
    {discovery ? <><p className={css.fine}>{discovery.scannedCount} observations scanned · {discovery.candidates.length} candidates retained · Checked {time(discovery.checkedAt)}. {discovery.method}</p>{discovery.candidates.length ? <ul className={css.scoutingCandidates}>{discovery.candidates.map(candidate => {
      const url = safeResearchSourceUrl(candidate.sourceUrl);
      return <li key={candidate.symbol}><header><div className={css.pills}><strong>{candidate.symbol}</strong><span>{candidate.name}</span><span className={css.pill}>Discovery rank {candidate.rank}</span></div><Link href={researchHref(null, candidate.symbol)} className={css.textButton} prefetch={false}>Inspect in Intelligence<ArrowUpRight size={12} aria-hidden /></Link></header><p>{candidate.reason}</p><div className={css.pills}><span className={css.pill}>{money(candidate.price)}</span><span className={css.pill}>{candidate.changePct === null ? "Change unavailable" : `${fmt(candidate.changePct, 2)}% observed change`}</span><span className={css.pill}>{candidate.state}</span></div><p className={css.fine}>{candidate.origins.join(" · ")} · Volume {fmt(candidate.volume, 0)} · Observed {time(candidate.observedAt)} · Retrieved {time(candidate.retrievedAt)}.</p>{url ? <a href={url} target="_blank" rel="noopener noreferrer" className={css.textButton}>{candidate.source}<ArrowUpRight size={12} aria-hidden /></a> : <span className={css.fine}>{candidate.source}</span>}<details className={css.recordDetails}><summary>Source fingerprint</summary><code>{candidate.sourceSha256}</code></details></li>;
    })}</ul> : <div className={css.empty}><strong>No usable candidates in this scan</strong>Inspect the recorded provider issues before retrying or changing the research universe.</div>}{discovery.issues.length > 0 && <details className={css.recordDetails}><summary>Discovery coverage and provider issues · {discovery.issues.length}</summary><ul>{discovery.issues.map((issue, index) => <li key={index}>{issue.message}</li>)}</ul></details>}</> : <div className={css.empty}><strong>No discovery scan recorded yet</strong>Scan now, or explicitly enable scheduled discovery while the worker is running.</div>}
  </section>;
}

export function AgentResearchTools({ tools, symbol }: { tools: DeskResearchTools | null; symbol: string }) {
  const economy = tools?.economy, charts = tools?.charts, scenarios = tools?.scenarios;
  return <section className={css.section} aria-label="Specialist research tools and historical scenarios"><div className={css.sectionHead}><div><p className={css.eyebrow}><BrainCircuit size={13} aria-hidden />Shared tools / specialist coverage</p><h2>One platform. Connected research.</h2><p>{tools ? `Recorded tools for ${tools.symbol}, checked ${time(tools.checkedAt)}. The agents consume these observed inputs alongside the Intelligence graph and shared outcome memory.` : "Each specialist has a defined research remit. Tool status and observations appear after an actual cycle; unavailable datasets remain visible as gaps."}</p></div></div>
    <div className={css.toolGrid}>
      <article className={css.toolCard}><span className={css.pill}>{economy?.status ?? "Not run"}</span><h3>Sentiment · economy &amp; risk appetite</h3><p>Macroeconomic observations and broad-market participation inform the willingness to take risk. Price momentum is a proxy, not a direct survey of investor intent.</p>{economy && <><small>Economic regime: {economy.snapshot?.regime ?? "Unavailable"} · {economy.snapshot?.series.length ?? 0} economic series.</small><small>Market proxy: {economy.riskAppetite?.symbol ?? "Unavailable"} · 20-session momentum {economy.riskAppetite?.momentum20Pct === null || economy.riskAppetite?.momentum20Pct === undefined ? "Unavailable" : `${fmt(economy.riskAppetite.momentum20Pct)}%`} · Observed {time(economy.riskAppetite?.asOf)}.</small>{economy.interpretationLimits.length > 0 && <details className={css.recordDetails}><summary>Interpretation limits</summary><ul>{economy.interpretationLimits.map((item, index) => <li key={index}>{item}</li>)}</ul></details>}</>}<Link href={researchHref(null, symbol)} prefetch={false} className={css.textButton}>Intelligence economy research<ArrowUpRight size={12} aria-hidden /></Link></article>
      <article className={css.toolCard}><span className={css.pill}>{charts?.status ?? "Not run"}</span><h3>Charts · technicals &amp; viability</h3><p>The same observed prices and metric calculations used by the Custom Board and Market Visuals support technical review.</p>{charts && <><small>{charts.barCount} historical bars · {charts.snapshot.session} · As of {time(charts.snapshot.asOf)}.</small><small>{charts.historyBasis || "Historical price basis unavailable"}</small><details className={css.recordDetails}><summary>Inspect recorded board metrics</summary><div className={css.tableWrap}><table className={css.table}><caption>{charts.snapshot.symbol} observations and calculations</caption><thead><tr><th scope="col">Metric</th><th scope="col">Value</th><th scope="col">Data state</th></tr></thead><tbody>{Object.entries(charts.snapshot.metrics).map(([key, metric]) => <tr key={key}><th scope="row">{key}<small>{metric.source} · {time(metric.asOf)}</small></th><td>{metric.display}</td><td>{metric.status}<small>{metric.detail}</small></td></tr>)}</tbody></table></div></details></>}<div className={css.actions}><Link href="/market-visuals" prefetch={false} className={css.textButton}>Market Visuals<ArrowUpRight size={12} aria-hidden /></Link><Link href="/workspace/custom-board" prefetch={false} className={css.textButton}>Custom Board<ArrowUpRight size={12} aria-hidden /></Link></div></article>
      <article className={css.toolCard}><span className={css.pill}>{scenarios?.status ?? "Not run"}</span><h3>Skeptic · Strategy Studio</h3><p>Historical regime comparisons and deterministic strategy tests challenge the current thesis across short and longer holding periods.</p>{scenarios && <><small>{scenarios.manifests.length} recorded datasets · {scenarios.strategies.filter(item => item.status === "complete").length} completed strategy tests · {scenarios.savedDefinitionsChecked} saved definitions checked.</small><small>Historical samples and holdout results are shown below with their limitations.</small></>}<Link href="/workspace/strategy-lab" prefetch={false} className={css.textButton}>Strategy Studio<ArrowUpRight size={12} aria-hidden /></Link></article>
    </div>
    {scenarios?.analogues && <details className={css.recordDetails}><summary>Historical analogues · short- and long-horizon evidence</summary><p>{scenarios.analogues.method}</p><p>{scenarios.analogues.basis}. Frequencies below describe past positive returns in similar recorded regimes; they are not calibrated probabilities of future profit.</p><div className={css.tableWrap}><table className={css.table}><caption>{symbol} historical conditional frequencies · validation starts {scenarios.analogues.validationStartDate ?? "Unavailable"}</caption><thead><tr><th scope="col">Horizon</th><th scope="col">Development sample</th><th scope="col">Holdout sample</th><th scope="col">Positive return frequency</th><th scope="col">95% sampling interval</th><th scope="col">Mean / worst return</th></tr></thead><tbody>{scenarios.analogues.scenarios.map(row => <tr key={row.horizonSessions}><th scope="row">{row.horizonSessions} sessions<small>{row.horizon}</small></th><td>{row.development.samples}</td><td>{row.validation.samples}<small>{row.validation.reliability}</small></td><td>{row.validation.positiveReturnFrequencyPct === null ? "Unavailable" : `${fmt(row.validation.positiveReturnFrequencyPct, 1)}%`}</td><td>{row.validation.wilson95Pct ? `${fmt(row.validation.wilson95Pct[0], 1)}%–${fmt(row.validation.wilson95Pct[1], 1)}%` : "Unavailable"}</td><td>{row.validation.meanReturnPct === null ? "—" : `${fmt(row.validation.meanReturnPct, 2)}%`} / {row.validation.worstReturnPct === null ? "—" : `${fmt(row.validation.worstReturnPct, 2)}%`}</td></tr>)}</tbody></table></div>{scenarios.analogues.warnings.length > 0 && <ul>{scenarios.analogues.warnings.map((warning, index) => <li key={index}>{warning}</li>)}</ul>}</details>}
    {scenarios && scenarios.strategies.length > 0 && <details className={css.recordDetails}><summary>Strategy test results · all recorded comparisons</summary><p>Hypothetical historical simulations. Development and validation results use the saved strategy definitions and cost assumptions. They do not establish a future return.</p><div className={css.tableWrap}><table className={css.table}><caption>Recorded Strategy Studio comparisons</caption><thead><tr><th scope="col">Strategy</th><th scope="col">Status</th><th scope="col">Full-period return</th><th scope="col">Validation return</th><th scope="col">Validation drawdown</th><th scope="col">Validation trade count</th></tr></thead><tbody>{scenarios.strategies.map((item, index) => <tr key={item.runId ?? `${item.name}-${index}`}><th scope="row">{item.name}<small>{item.source === "user-definition" ? "Your saved definition" : "Fixed comparison template"}</small></th><td>{item.status}<small>{item.error || item.warnings.join(" · ")}</small></td><td>{item.strategy ? `${fmt(item.strategy.totalReturnPct)}%` : "Unavailable"}</td><td>{item.validation ? `${fmt(item.validation.totalReturnPct)}%` : "Unavailable"}</td><td>{item.validation ? `${fmt(item.validation.maxDrawdownPct)}%` : "Unavailable"}</td><td>{item.validation?.tradeCount ?? "Unavailable"}<small>Validation begins {item.validationStartDate ?? "Unavailable"}</small></td></tr>)}</tbody></table></div>{scenarios.skippedDefinitions.length > 0 && <ul>{scenarios.skippedDefinitions.map(item => <li key={item.id}>{item.name}: {item.reason}</li>)}</ul>}</details>}
    {scenarios && scenarios.manifests.length > 0 && <details className={css.recordDetails}><summary>Historical dataset provenance</summary><ul>{scenarios.manifests.map(manifest => <li key={manifest.id}>{manifest.symbol} · {manifest.provider} · {manifest.barCount} bars · {manifest.firstDate} to {manifest.lastDate}<small>Retrieved {time(manifest.retrievedAt)} · {manifest.vintage}</small><code>{manifest.sourceSha256}</code></li>)}</ul></details>}
    {tools && tools.issues.length > 0 && <div className={css.notice} data-tone="caution"><strong>Tool coverage needs review</strong><ul>{tools.issues.map((issue, index) => <li key={index} className={css.fine}>{issue.tool}: {issue.message}</li>)}</ul></div>}
  </section>;
}

/** Only recorded tool research may link to these read-only, authenticated ledgers. */
export function agentEvidenceHref(evidence: AgentEvidence) {
  const value = evidence.url.trim();
  if (evidence.kind === "tool-research") {
    if (value === "/api/strategy-lab/datasets") return value;
    if (value.startsWith("/api/strategy-lab/runs?")) {
      try {
        const parsed = new URL(value, "https://slice.invalid");
        const id = parsed.searchParams.get("id"), keys = [...parsed.searchParams.keys()];
        if (parsed.origin === "https://slice.invalid" && parsed.pathname === "/api/strategy-lab/runs" && !parsed.hash && keys.length === 1 && keys[0] === "id" && id && /^[a-zA-Z0-9_-]{1,100}$/.test(id)) return `/api/strategy-lab/runs?${new URLSearchParams({ id })}`;
      } catch { /* Keep unsupported provenance references as plain text. */ }
    }
  }
  return safeResearchSourceUrl(value);
}

export function EvidenceLink({ evidence }: { evidence: AgentEvidence }) {
  const href = agentEvidenceHref(evidence);
  return <li>{href ? <a href={href} target="_blank" rel="noopener noreferrer">{evidence.title}<ArrowUpRight size={12} aria-hidden /></a> : <strong>{evidence.title}</strong>}<small>{evidence.source} · {evidenceKind(evidence.kind)}</small><small>Observed or published {time(evidence.observedAt)} · Retrieved {time(evidence.retrievedAt)}</small>{evidence.summary && <p>{evidence.summary}</p>}{Object.keys(evidence.metrics).length > 0 && <details><summary>Recorded inputs</summary><dl>{Object.entries(evidence.metrics).map(([key, value]) => <div key={key}><dt>{key}</dt><dd>{value === null ? "Unavailable" : String(value)}</dd></div>)}</dl></details>}</li>;
}

export function AgentRoleCard({ role, finding, evidence }: { role: AgentRole; finding?: AgentFinding; evidence: AgentEvidence[] }) {
  const Icon = ROLE_ICONS[role], sources = new Map(evidence.map(item => [item.id, item]));
  return <article className={css.role} data-role={role} aria-label={`${AGENT_ROLE_LABELS[role]} agent`}>
    <div className={css.roleHead}><div className={css.roleIcon}><Icon size={19} aria-hidden /></div><div><h3>{AGENT_ROLE_LABELS[role]}</h3><p>{ROLE_TAGS[role]}</p></div><span className={css.roleStatus}>{finding?.status === "complete" ? "Completed" : finding?.status === "failed" ? "Failed" : finding?.status === "skipped" ? "Skipped" : "Not run"}</span></div>
    {!finding ? <p className={css.roleEmpty}>{AGENT_ROLE_MISSIONS[role]}</p> : <>
      <div className={css.pills}><span className={css.pill}>{finding.stance === "insufficient" ? "Insufficient evidence" : finding.stance}</span>{finding.veto && <span className={css.pill} data-tone="negative">Veto active</span>}</div>
      <p className={css.roleText}>{finding.summary || "No supported summary was returned."}</p>
      {finding.horizonViews?.length ? <details><summary>Short- and long-horizon assessment</summary>{finding.horizonViews.map((view, index) => <p key={index}><strong>{view.horizon === "short" ? "Short horizon" : "Long horizon"} · {view.stance}</strong><br />{view.summary}{view.evidenceIds.length > 0 && <small> Evidence: {view.evidenceIds.join(", ")}</small>}</p>)}</details> : null}
      {finding.lessonsReviewed?.length ? <p className={css.roleNote}>{finding.lessonsReviewed.length} saved lesson{finding.lessonsReviewed.length === 1 ? "" : "s"} reviewed in this report.</p> : null}
      {finding.error && <p className={css.roleError}>{finding.error}</p>}
      {finding.findings.length > 0 && <details><summary>Reasoning &amp; cited evidence · {finding.findings.length}</summary><ul>{finding.findings.map((item, index) => <li key={index}>{item.claim}<ul>{item.evidenceIds.map(id => {
        const source = sources.get(id), url = source ? agentEvidenceHref(source) : "";
        return <li key={id}>{source && url ? <a href={url} target="_blank" rel="noopener noreferrer">{source.title}</a> : source?.title ?? "Source unavailable in this recorded cycle"}{source && source.kind !== "scored-evidence" && <span> · {evidenceKind(source.kind)}</span>}</li>;
      })}</ul></li>)}</ul></details>}
      {(finding.risks.length > 0 || finding.missingData.length > 0) && <details><summary>Risks &amp; missing inputs</summary>{finding.risks.length > 0 && <ul>{finding.risks.map((risk, index) => <li key={index}>{risk}</li>)}</ul>}{finding.missingData.length > 0 && <><strong>Missing inputs</strong><ul>{finding.missingData.map((item, index) => <li key={index}>{item}</li>)}</ul></>}</details>}
      {Boolean(finding.toolCalls?.length) && <details><summary>Recorded evidence lookups</summary><ul>{finding.toolCalls?.map((call, index) => <li key={index}>{call.tool} · {call.evidenceIds.length} referenced records · {time(call.at)}</li>)}</ul></details>}
      <div className={css.roleFooter}><span>{finding.model || "No model response"}</span><strong>{finding.status === "complete" ? finding.action.toUpperCase() : "No executable proposal"}</strong></div><p className={css.roleNote}>{finding.round ? `Round ${finding.round} · ${finding.phase ?? "report"} · ` : ""}Completed {time(finding.completedAt)}</p>
    </>}
  </article>;
}

type PolicyNumber = Exclude<keyof DeskPolicy, "version" | "allowedSymbols">;
type FieldSpec = { key: PolicyNumber; label: string; min: number; max: number; step?: number; note: string; optional?: boolean };
const CAPITAL: FieldSpec[] = [
  { key: "maxPositionPct", label: "Maximum position (% of equity)", min: 1, max: 100, note: "Upper limit for any new paper position." },
  { key: "maxExposurePct", label: "Maximum total exposure (%)", min: 1, max: 100, note: "All open paper exposure must fit this limit." },
  { key: "minCashPct", label: "Minimum cash reserve (%)", min: 0, max: 99, note: "Exposure plus this reserve cannot exceed 100%." },
  { key: "maxDailyLossPct", label: "Daily loss limit (%)", min: .1, max: 20, step: .1, note: "Stops new exposure after the session loss limit is reached." },
  { key: "maxTradesPerDay", label: "Maximum orders per session", min: 1, max: 100, note: "Limits new entries; protective and closing exits remain available." },
  { key: "cooldownMinutes", label: "Entry cooldown (minutes)", min: 0, max: 240, note: "Minimum interval before another new entry." },
];
const EXITS: FieldSpec[] = [
  { key: "stopLossPct", label: "Stop-loss (%)", min: .1, max: 25, step: .1, note: "A loss threshold based on the recorded purchase fill." },
  { key: "takeProfitPct", label: "Take-profit (%)", min: .1, max: 100, step: .1, optional: true, note: "Leave empty to disable this optional profit exit." },
  { key: "trailingStopPct", label: "Trailing stop (%)", min: .1, max: 25, step: .1, optional: true, note: "Tracks the highest observed price after entry; empty disables it." },
  { key: "maxHoldingMinutes", label: "Maximum holding time (minutes)", min: 1, max: 390, note: "Exits on a usable observation after the holding limit." },
  { key: "flattenBeforeCloseMinutes", label: "Close before session end (minutes)", min: 1, max: 60, note: "Aims to close before the modeled regular session ends." },
];
const ADVANCED: FieldSpec[] = [
  { key: "minResearchConfidence", label: "Minimum research confidence / 100", min: 40, max: 100, note: "Cannot go below the platform’s 40-point evidence standard." },
  { key: "minEvidenceCoverage", label: "Minimum evidence coverage / 100", min: 40, max: 100, note: "Requires the recorded research inputs to meet this floor." },
  { key: "maxQuoteAgeSeconds", label: "Maximum quote age (seconds)", min: 60, max: 900, note: "Also requires a confirmed live intraday observation and open market." },
  { key: "maxDecisionAgeSeconds", label: "Maximum decision age (seconds)", min: 60, max: 3600, note: "Expired proposals cannot create new exposure." },
  { key: "maxPriceDriftBps", label: "Maximum entry price drift (basis points)", min: 1, max: 500, note: "Rejects an entry if the current observed price moved too far." },
  { key: "slippageBps", label: "Simulated slippage (basis points)", min: 0, max: 100, step: .1, note: "Applied against each paper fill. 100 basis points equals 1%." },
  { key: "feeBps", label: "Simulated fee (basis points)", min: 0, max: 100, step: .1, note: "A percentage cost added to each simulated order." },
  { key: "commissionUsd", label: "Simulated fixed commission (USD)", min: 0, max: 100, step: .01, note: "A fixed cost per paper fill, in addition to percentage fees." },
];

function DeskSettingsForm(props: Pick<AgentDeskDashboardProps, "draft" | "symbolsText" | "scoutUniverseText" | "dirty" | "conflict" | "pending" | "onDraft" | "onSymbols" | "onScoutUniverse" | "onSave" | "onDiscard"> & { desk: AgentDeskView; disabled: boolean }) {
  const { draft, desk, disabled } = props; if (!draft) return null;
  const scouting = draft.scouting ?? DEFAULT_DESK_SCOUTING;
  const updateScouting = (update: Partial<typeof scouting>) => props.onDraft(settings => ({ ...settings, scouting: { ...(settings.scouting ?? DEFAULT_DESK_SCOUTING), ...update } }));
  const operations = draft.operations ?? DEFAULT_DESK_OPERATIONS;
  const updateOperations = (update: Partial<typeof operations>) => props.onDraft(settings => ({ ...settings, operations: { ...(settings.operations ?? DEFAULT_DESK_OPERATIONS), ...update } }));
  const edit = (key: PolicyNumber, value: string, optional = false) => props.onDraft(settings => ({ ...settings, policy: { ...settings.policy, [key]: value === "" ? optional ? null : NaN : Number(value) } }));
  const fields = (items: FieldSpec[]) => <div className={css.fields}>{items.map(field => <label className={css.field} key={field.key}><span>{field.label}</span><input type="number" min={field.min} max={field.max} step={field.step ?? 1} required={!field.optional} value={typeof draft.policy[field.key] === "number" && Number.isFinite(draft.policy[field.key]) ? draft.policy[field.key]! : ""} disabled={disabled} onChange={event => edit(field.key, event.target.value, field.optional)} /><small>{field.note}</small></label>)}</div>;
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); props.onSave(); };
  return <details className={css.settings}>
    <summary><span><Settings2 size={15} aria-hidden style={{ display: "inline", verticalAlign: "-3px", marginRight: 8 }} />Your trading safeguards</span><small>{props.dirty ? "Unsaved changes" : `Saved revision ${desk.revision}`}</small></summary>
    <form className={css.settingsBody} onSubmit={submit}>
      {disabled && <p className={css.notice}>Pause entries and let the current cycle finish before editing safeguards. The kill switch remains available at any time.</p>}
      {props.conflict && <p className={css.notice} data-tone="caution" role="alert">Safeguards changed in another session. Your draft has been preserved. Discard these edits to load the current policy before making another change.</p>}
      <fieldset disabled={disabled}><legend>Instrument &amp; schedule</legend><div className={css.fields}>
        <label className={css.field}><span>Instrument to monitor</span><input type="text" required autoComplete="off" maxLength={32} pattern="[A-Z0-9\^][A-Z0-9.\^:\-]{0,31}" value={draft.symbol} disabled={disabled || Boolean(desk.account.position)} onChange={event => props.onDraft(value => ({ ...value, symbol: event.target.value.toUpperCase() }))} /><small>{desk.account.position ? "Locked to the held instrument until the position closes." : "Research a stock, ETF, or explicit index such as INDEX:SPX. Native indices remain research-only."}</small></label>
        <label className={css.field}><span>Autonomous research interval (minutes)</span><input type="number" min={5} max={240} step={1} required value={Number.isFinite(draft.intervalMinutes) ? draft.intervalMinutes : ""} onChange={event => props.onDraft(value => ({ ...value, intervalMinutes: event.target.value === "" ? NaN : Number(event.target.value) }))} /><small>Schedules fresh research when the worker is running.</small></label>
        <label className={css.field}><span>Starting paper capital (USD)</span><input type="number" min={100} max={1000000000} step={.01} required value={Number.isFinite(draft.initialCapital) ? draft.initialCapital : ""} disabled={disabled || Boolean(desk.account.lastFillAt)} onChange={event => props.onDraft(value => ({ ...value, initialCapital: event.target.value === "" ? NaN : Number(event.target.value) }))} /><small>{desk.account.lastFillAt ? "Locked after the first fill to preserve performance accounting." : "Simulated capital only. No deposit or brokerage account is involved."}</small></label>
        <label className={`${css.field} ${css.wideField}`}><span>Allowed stock &amp; ETF symbols</span><input type="text" required autoComplete="off" maxLength={340} value={props.symbolsText} onChange={event => props.onSymbols(event.target.value.toUpperCase())} /><small>Choose 1–20 distinct symbols, separated by commas. An equity must be allowed to open a position; a held equity must remain allowed. Index research does not authorize an index trade.</small></label>
      </div></fieldset>
      <fieldset disabled={disabled}><legend>Continuous Scout discovery</legend><div className={css.fields}>
        <label className={css.toggle}><input type="checkbox" checked={scouting.enabled} onChange={event => updateScouting({ enabled: event.target.checked })} /><span>Enable scheduled candidate discovery<small>The running worker scans recorded market movers, your watchlist, and the optional universe below.</small></span></label>
        <label className={css.toggle}><input type="checkbox" checked={scouting.autoResearch} onChange={event => updateScouting({ autoResearch: event.target.checked })} /><span>Research discovered candidates automatically<small>Used only while scheduled discovery is enabled. It does not authorize orders or add symbols to the trading allowlist.</small></span></label>
        <label className={css.field}><span>Discovery interval (minutes)</span><input type="number" min={5} max={240} step={1} required value={Number.isFinite(scouting.intervalMinutes) ? scouting.intervalMinutes : ""} onChange={event => updateScouting({ intervalMinutes: event.target.value === "" ? NaN : Number(event.target.value) })} /><small>The worker and provider availability determine the actual scan cadence.</small></label>
        <label className={css.field}><span>Maximum candidates per scan</span><input type="number" min={1} max={12} step={1} required value={Number.isFinite(scouting.maxCandidates) ? scouting.maxCandidates : ""} onChange={event => updateScouting({ maxCandidates: event.target.value === "" ? NaN : Number(event.target.value) })} /><small>Ranked discoveries for review; this is not a profit probability.</small></label>
        <label className={`${css.field} ${css.wideField}`}><span>Additional research universe</span><input type="text" autoComplete="off" maxLength={1300} value={props.scoutUniverseText} onChange={event => props.onScoutUniverse(event.target.value.toUpperCase())} /><small>Optional: up to 40 symbols separated by commas. Researching an instrument grants no trading permission.</small></label>
      </div></fieldset>
      <fieldset disabled={disabled}><legend>Workload, research access &amp; operating cost</legend><div className={css.fields}>
        <label className={css.field}><span>Research cadence</span><select value={operations.mode} onChange={event => updateOperations({ mode: event.target.value === "responsive" ? "responsive" : "economy" })}><option value="economy">Economy · reuse unchanged observations</option><option value="responsive">Responsive · review more often</option></select><small>Economy avoids repeating a full AI deliberation when no meaningful new signal is recorded. Protective checks remain separate.</small></label>
        <label className={css.toggle}><input type="checkbox" checked={operations.helpersEnabled} onChange={event => updateOperations({ helpersEnabled: event.target.checked })} /><span>Delegate supporting work<small>Add focused subagents when the recorded workload warrants them. The six accountable roles and Chief remain in control.</small></span></label>
        <label className={css.field}><span>Maximum helpers per cycle</span><input type="number" min={0} max={12} step={1} required disabled={!operations.helpersEnabled} value={Number.isFinite(operations.maxHelpers) ? operations.maxHelpers : ""} onChange={event => updateOperations({ maxHelpers: event.target.value === "" ? NaN : Number(event.target.value) })} /><small>A ceiling, not a fixed swarm. Only helpers selected for actual work are called.</small></label>
        <label className={css.field}><span>Concurrent helpers</span><input type="number" min={1} max={3} step={1} required disabled={!operations.helpersEnabled} value={Number.isFinite(operations.maxConcurrentHelpers) ? operations.maxConcurrentHelpers : ""} onChange={event => updateOperations({ maxConcurrentHelpers: event.target.value === "" ? NaN : Number(event.target.value) })} /><small>Bounded parallel work controls provider demand. Provider charges depend on actual requests and your subscription.</small></label>
        <label className={css.toggle}><input type="checkbox" checked={operations.internetResearch} onChange={event => updateOperations({ internetResearch: event.target.checked })} /><span>Use configured internet research<small>Retrieve public research through available server tools and retain the sources. A missing provider remains visible as a coverage gap.</small></span></label>
        <label className={css.toggle}><input type="checkbox" checked={operations.sharedResearch} onChange={event => updateOperations({ sharedResearch: event.target.checked })} /><span>Read permissioned shared research<small>Use public-market research explicitly contributed to the shared library. Private client records and other users’ account data are excluded.</small></span></label>
      </div></fieldset>
      <fieldset disabled={disabled}><legend>Capital &amp; session limits</legend>{fields(CAPITAL)}</fieldset>
      <fieldset disabled={disabled}><legend>Protective exits</legend>{fields(EXITS)}<p className={css.fine}>An open position keeps the exit rules recorded when it was entered. Triggers are assessed on observed prices; gaps, missed observations, and costs can cause the actual simulated exit to differ from a threshold.</p></fieldset>
      <details><summary className={css.textButton}>Evidence, freshness &amp; simulated costs</summary><fieldset disabled={disabled}><legend>Entry quality and cost assumptions</legend>{fields(ADVANCED)}</fieldset></details>
      <div className={css.settingsFooter}><p>These limits are checked by the execution controls. AI agents cannot edit your policy, lower its evidence floor, or bypass a veto.</p><div className={css.actions}><button type="button" className={css.secondary} disabled={!props.dirty || Boolean(props.pending)} onClick={props.onDiscard}>Discard edits</button><button type="submit" className={css.button} disabled={disabled || !props.dirty || props.conflict}>{props.pending === "settings" ? <RefreshCw size={13} className={css.loading} aria-hidden /> : <ShieldCheck size={13} aria-hidden />}{props.pending === "settings" ? "Saving safeguards…" : "Save safeguards"}</button></div></div>
    </form>
  </details>;
}

function RecentFills({ cycles }: { cycles: DeskCycle[] }) {
  const fills = cycles.flatMap(cycle => cycle.fill ? [cycle.fill] : []);
  return <div style={{ marginTop: 20 }}>{fills.length ? <div className={css.tableWrap}><table className={css.table}><caption>Paper fills in the recent saved cycle history</caption><thead><tr><th scope="col">Observed / filled</th><th scope="col">Order</th><th scope="col">Fill price</th><th scope="col">Fees</th><th scope="col">Realized P&amp;L</th></tr></thead><tbody>{fills.map(fill => <tr key={fill.id}><td>{time(fill.observedAt)}<small>Recorded {time(fill.filledAt)}</small></td><th scope="row">{fill.side} {fmt(fill.quantity, 0)} {fill.symbol}<small>{fill.reason}</small></th><td>{money(fill.fillPrice)}<small>Observed {money(fill.observedPrice)}</small></td><td>{money(fill.fees)}</td><td data-tone={fill.realizedPnl < 0 ? "negative" : "positive"}>{fill.side === "SELL" ? money(fill.realizedPnl) : "Open position"}</td></tr>)}</tbody></table></div> : <p className={css.fine}>No simulated fills appear in the recent cycle history. Holds and blocked entries do not become fabricated trades.</p>}</div>;
}
